<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../services/api';import PageHeader from'../../components/PageHeader.vue';const wallet=ref({balance:0,entries:[]});const orders=ref<any[]>([]);const products=ref<any[]>([]);const labels:Record<string,string>={PENDING:'待支付',PAID:'已支付',CANCELLED:'已取消',REFUNDING:'退款中',REFUNDED:'已退款'};onMounted(async()=>{const[w,o,p]=await Promise.all([api.get('/wallet'),api.get('/orders'),api.get('/catalog/products')]);wallet.value=w.data;orders.value=o.data;products.value=p.data;});const money=(n:number)=>(n/100).toFixed(2);</script><template><main class="page business-page"><PageHeader title="钱包与订单" subtitle="金币、会员与商品"/><section class="balance-hero"><small>可用金币</small><strong>{{wallet.balance.toLocaleString()}}</strong><button>充值金币</button></section><h2 class="block-title">推荐商品</h2><div class="product-scroll"><article v-for="p in products" :key="p.id"><span>{{p.type==='COIN_PACKAGE'?'◈':p.type==='MEMBERSHIP'?'✦':'▣'}}</span><b>{{p.name}}</b><small>¥ {{money(p.price)}}</small></article></div><h2 class="block-title">我的订单</h2><section class="list-panel"><article v-for="o in orders" :key="o.id" class="order-row"><div><b>订单 {{o.id.slice(0,8)}}</b><small>¥ {{money(o.totalAmount)}}</small></div><span class="status-chip">{{labels[o.status]??o.status}}</span></article><p v-if="!orders.length" class="empty-state">暂无订单</p></section></main></template>
